RESET ROLE;
SELECT test_assert((SELECT sender_email='noreply@mail.tryjalla.com' AND followup_sender_email='contact@tryjalla.com' AND application_sender_email='partner@tryjalla.com' FROM communication_settings WHERE id),'repair restores the three selected sending addresses');
SELECT test_assert((SELECT (to_jsonb(s) - 'sender_email' - 'updated_at' - 'followup_sender_email' - 'application_sender_email')=v.settings FROM communication_settings s CROSS JOIN communication_upgrade_snapshot v WHERE s.id),'repair preserves delivery switch, test recipients, owner and cadence');
SELECT test_assert((SELECT jsonb_agg(to_jsonb(s) ORDER BY key) FROM lifecycle_sequences s)=(SELECT sequences FROM communication_upgrade_snapshot),'repair preserves all journey enablement and copy configuration');
SELECT test_assert((SELECT jsonb_agg(to_jsonb(p) ORDER BY email) FROM communication_preferences p)=(SELECT preferences FROM communication_upgrade_snapshot),'repair preserves consent, capability tokens and blocked recipients');
SELECT test_assert((SELECT (to_jsonb(m) - 'sent_at')=v.message AND m.sent_at IS NOT NULL FROM communication_messages m CROSS JOIN communication_upgrade_snapshot v WHERE m.id=test_id(1701)),'repair preserves old reply identity, body, payload and provider status');
SELECT test_assert((SELECT (to_jsonb(f) - 'last_reviewed_at')=v.followup FROM followup_queue f CROSS JOIN communication_upgrade_snapshot v WHERE f.enrollment_id=test_id(1700)),'repair leaves existing staff contact history unchanged');
UPDATE communication_messages SET status='delivered' WHERE id=test_id(1701);
SELECT test_assert((SELECT attempt_count=3 FROM followup_queue WHERE enrollment_id=test_id(1700)),'repeated callback cannot count a pre-upgrade staff reply again');
SELECT test_assert(to_regclass('public.communication_issues') IS NOT NULL,'repair restores incoming-mail issue tracking');
SELECT test_assert((SELECT relrowsecurity FROM pg_class WHERE oid='public.communication_issues'::regclass),'issue tracking has RLS after upgrade');
SET ROLE authenticated;
SELECT set_config('test.actor',test_id(13)::text,false);
SELECT test_assert(NOT EXISTS(SELECT 1 FROM communication_settings),'ordinary users cannot read repaired admin settings');
SELECT test_assert(NOT EXISTS(SELECT 1 FROM communication_issues),'ordinary users cannot read receiving diagnostics');
SELECT set_config('test.actor',test_id(4)::text,false);
SELECT admin_save_communication_settings(jsonb_build_object('sender_name','Groundwork','sender_email','welcome@test.example','followup_sender_email','followup@test.example','application_sender_email','applications@test.example','reply_domain','replies.test.example','delivery_enabled',true,'test_recipients',ARRAY['1@test.example','11@test.example','12@test.example','13@test.example']),(SELECT updated_at FROM communication_settings WHERE id));
SELECT test_assert((SELECT followup_sender_email='followup@test.example' AND application_sender_email='applications@test.example' FROM communication_settings WHERE id),'repaired settings RPC saves the separate sending purposes');
RESET ROLE;
SELECT 'COMMUNICATION_UPGRADE_OK';
